// Calcula la fecha de ayer en Europe/Madrid
const now = new Date();
const madridDate = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Madrid' }).format(now);
const yesterday = new Date(madridDate);
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().split('T')[0];

return [{
  json: {
    date: date,
    latitude: 40.4168,
    longitude: -3.7038,
    timezone: 'Europe/Madrid',
    weatherUrl: `https://archive-api.open-meteo.com/v1/archive?latitude=40.4168&longitude=-3.7038&start_date=${date}&end_date=${date}&hourly=temperature_2m,precipitation&timezone=Europe%2FMadrid`,
    airUrl: `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=40.4168&longitude=-3.7038&start_date=${date}&end_date=${date}&hourly=ozone,carbon_dioxide&timezone=Europe%2FMadrid`
  }
}];

// Empaqueta las dos respuestas de API en un objeto con la fecha
const date = $('Code in JavaScript').item.json.date;

// Con Merge en modo combinar, los items vienen como array
const allItems = $input.all();

// El primer item es weather, el segundo es air quality
// Si solo llega 1 item, los datos están fusionados en el mismo objeto
let weather, air;

if (allItems.length >= 2) {
  weather = allItems[0].json;
  air = allItems[1].json;
} else {
  // Fallback: un solo item con ambos datos
  weather = allItems[0].json;
  air = allItems[0].json;
}

return [{
  json: {
    date: date,
    weather: weather,
    air_quality: air
  }
}];

