// Divide el item en 24 items, uno por hora
const date = $('Code in JavaScript').item.json.date;
const data = $input.item.json;

// Los datos pueden venir de dos estructuras distintas
const weather = data.weather || data;
const air = data.air_quality || data;

const items = [];

for (let i = 0; i < 24; i++) {
  items.push({
    json: {
      date: date,
      hour: i,
      time: (weather.hourly?.time || [])[i] ?? `${date}T${String(i).padStart(2,'0')}:00`,
      latitude: weather.latitude ?? 40.4168,
      longitude: weather.longitude ?? -3.7038,
      temperature_2m: (weather.hourly?.temperature_2m || [])[i] ?? null,
      temperature_2m_unit: weather.hourly_units?.temperature_2m ?? '°C',
      precipitation: (weather.hourly?.precipitation || [])[i] ?? null,
      precipitation_unit: weather.hourly_units?.precipitation ?? 'mm',
      ozone: (air.hourly?.ozone || [])[i] ?? null,
      ozone_unit: air.hourly_units?.ozone ?? 'μg/m³',
      carbon_dioxide: (air.hourly?.carbon_dioxide || [])[i] ?? null,
      carbon_dioxide_unit: air.hourly_units?.carbon_dioxide ?? 'ppm'
    }
  });
}

return items;
